"""Paths and settings. Every value can be changed in the .env file at the project root."""

import os
from pathlib import Path

from dotenv import load_dotenv

PROJECT_DIR = Path(__file__).resolve().parents[2]
load_dotenv(PROJECT_DIR / ".env")

BACKEND_DIR = PROJECT_DIR / "backend"
# The tests set GUIDELY_DATA_DIR to a temporary copy, so they never change the real documents, index or logs.
DATA_DIR = Path(os.getenv("GUIDELY_DATA_DIR", BACKEND_DIR / "data"))
DOCS_DIR = DATA_DIR / "sample-docs"
CATEGORIES_FILE = DATA_DIR / "categories.json"

# Everything generated by indexing lives here and can be rebuilt with "Re-index all".
INDEX_DIR = DATA_DIR / "index"
CACHE_FILE = INDEX_DIR / "embedding_cache.json"
QUERY_CACHE_FILE = INDEX_DIR / "query_cache.json"
INDEX_FILE = INDEX_DIR / "index.faiss"
CHUNKS_FILE = INDEX_DIR / "chunks.json"
FILE_HASHES_FILE = INDEX_DIR / "file_hashes.json"

LOGS_DIR = DATA_DIR / "logs"
QUERY_LOG = LOGS_DIR / "queries.jsonl"
ERROR_LOG = LOGS_DIR / "errors.jsonl"
INDEX_LOG = LOGS_DIR / "index.jsonl"
# Log lines older than this are deleted on startup. 0 keeps them forever.
LOG_RETENTION_DAYS = int(os.getenv("LOG_RETENTION_DAYS", "30"))

SUPPORTED_TYPES = {".txt", ".md", ".pdf"}
MAX_UPLOAD_MB = int(os.getenv("MAX_UPLOAD_MB", "5"))

CHUNK_WORDS = int(os.getenv("CHUNK_WORDS", "250"))
EMBEDDING_MODEL = os.getenv("EMBEDDING_MODEL", "BAAI/bge-small-en-v1.5")
MAX_CACHED_QUESTIONS = int(os.getenv("MAX_CACHED_QUESTIONS", "500"))

TOP_K = int(os.getenv("TOP_K", "3"))
MIN_SCORE = float(os.getenv("MIN_SCORE", "0.45"))
MAX_HISTORY = int(os.getenv("MAX_HISTORY", "3"))

OLLAMA_URL = os.getenv("OLLAMA_URL", "http://127.0.0.1:11434")
LLM_MODEL = os.getenv("LLM_MODEL", "")
LLM_TIMEOUT = float(os.getenv("LLM_TIMEOUT", "60"))
